result = await mcp.call_tool("tools", "ox-bridge-write", {"path": "/workspace/sokoban.py", "content": """"Sokoban engine plus optimal BFS solver."""

from collections import deque

MOVES = {
    "u": (-1, 0),
    "d": (1, 0),
    "l": (0, -1),
    "r": (0, 1),
}

WALL, FLOOR, GOAL = "#", "-", "X"


def parse_level(text):
    """Return (walls, goals, player, boxes). Cells are (row, col) tuples."""
    walls, goals, boxes = set(), set(), None
    player = None
    for r, line in enumerate(text.strip("\n").splitlines()):
        for c, ch in enumerate(line):
            pos = (r, c)
            if ch == WALL:
                walls.add(pos)
            elif ch == GOAL:
                goals.add(pos)
            elif ch == "@":
                player = pos
            elif ch == "$":
                if boxes is not None:
                    raise ValueError("multiple players not supported")
                boxes = {pos} if boxes is None else boxes | {pos}
    if player is None:
        raise ValueError("level has no player")
    return walls, frozenset(goals), player, frozenset(boxes)


class Sokoban:
    """Engine: applies udlr move strings; pushes allowed onto floor/goal only."""

    def __init__(self, level_text):
        self.walls, self.goals, self.player, self.boxes = parse_level(level_text)

    def step(self, mv):
        """Apply one move. Returns True if the move was legal, False otherwise."""
        dr, dc = MOVES[mv]
        nxt = (self.player[0] + dr, self.player[1] + dc)
        if nxt in self.walls:
            return False
        if nxt in self.boxes:
            beyond = (nxt[0] + dr, nxt[1] + dc)
            # Push allowed onto floor/goal only (not wall, not another box).
            if beyond in self.walls or beyond in self.boxes:
                return False
            self.boxes = (self.boxes - {nxt}) | {beyond}
        self.player = nxt
        return True

    def move(self, seq):
        for mv in seq.lower():
            if mv not in MOVES:
                raise ValueError(f"unknown move: {mv!r}")
            if not self.step(mv):
                return False
        return True

    @property
    def solved(self):
        return self.goals <= self.boxes


def _is_corner_deadlock(pos, walls, goals):
    """A box on a non-goal square in a corner can never be moved again usefully."""
    if pos in goals:
        return False
    r, c = pos
    up, down = (r - 1, c) in walls, (r + 1, c) in walls
    left, right = (r, c - 1) in walls, (r, c + 1) in walls
    return (up or down) and (left or right)


def solve(level_text):
    """BFS over (player, boxes) states. Returns a shortest move string,
    or None if unsolvable. Prunes corner deadlocks."""
    walls, goals, player, boxes = parse_level(level_text)

    def dead(boxes):
        return any(_is_corner_deadlock(b, walls, goals) for b in boxes)

    start = (player, boxes)
    if goals <= boxes:
        return ""
    if dead(boxes):
        return None

    queue = deque([start])
    parent = {start: None}  # state -> (prev_state, move)
    while queue:
        state = queue.popleft()
        ppos, bxs = state
        for mv, (dr, dc) in MOVES.items():
            np = (ppos[0] + dr, ppos[1] + dc)
            if np in walls:
                continue
            nbxs = bxs
            if np in bxs:
                beyond = (np[0] + dr, np[1] + dc)
                if beyond in walls or beyond in bxs:
                    continue
                nbxs = (bxs - {np}) | {beyond}
                if goals <= nbxs:
                    # Reconstruct path.
                    path = [mv]
                    cur = state
                    while parent[cur] is not None:
                        cur, pmv = parent[cur]
                        path.append(pmv)
                    return "".join(reversed(path))
                if dead(nbxs):
                    continue
            nstate = (np, nbxs)
            if nstate not in parent:
                parent[nstate] = (state, mv)
                queue.append(nstate)
    return None
